require_once __DIR__.'/../inc/platform_health.php';function infra_test($condition,$message){if(!$condition){fwrite(STDERR,'FAIL: '.$message.PHP_EOL);exit(1);}echo 'PASS: '.$message.PHP_EOL;}$file=tempnam(sys_get_temp_dir(),'tickex-infra-');$pdo=new PDO('sqlite:'.$file);$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->exec('CREATE TABLE sample(id INTEGER PRIMARY KEY,value TEXT);INSERT INTO sample(value) VALUES("ok")');$report=tickex_platform_health_report($pdo);$byKey=array();foreach($report['checks'] as $check)$byKey[$check['key']]=$check;infra_test(isset($byKey['php'],$byKey['sqlite'],$byKey['integrity'],$byKey['journal'],$byKey['backup']),'report covers runtime database concurrency and backups');infra_test($byKey['integrity']['status']==='ok','healthy SQLite copy passes quick integrity check');infra_test($byKey['php']['value']===PHP_VERSION,'report uses the effective web runtime version');infra_test(isset($report['counts']['critical'],$report['counts']['warning'],$report['overall']),'report exposes an actionable summary');infra_test(strpos(json_encode($report),'access_token')===false,'report never exposes payment credentials');@unlink($file);echo 'ALL PLATFORM HEALTH TESTS PASSED'.PHP_EOL;
